DROP TABLE IF EXISTS replacement_requests_archive CASCADE;
DROP TABLE IF EXISTS replacement_requests CASCADE;
DROP TABLE IF EXISTS timetable CASCADE;
DROP TABLE IF EXISTS teachers CASCADE;
DROP SCHEMA IF EXISTS api CASCADE;
DROP TABLE IF EXISTS teacher_competencies CASCADE;
CREATE SCHEMA api;
CREATE TABLE teachers (name TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE timetable (id SERIAL PRIMARY KEY, subject TEXT NOT NULL, classes INTEGER NOT NULL, dinner TEXT, team TEXT NOT NULL, teacher TEXT NOT NULL, date DATE NOT NULL, day_of_week INTEGER NOT NULL, week_num INTEGER NOT NULL, num_den TEXT NOT NULL, audiense TEXT, type TEXT, is_replacement BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE replacement_requests (id SERIAL PRIMARY KEY, teacher_name TEXT NOT NULL, request_date DATE NOT NULL, week_num INTEGER NOT NULL, num_den TEXT, classes INTEGER NOT NULL, subject TEXT NOT NULL, team TEXT NOT NULL, status TEXT DEFAULT 'pending', replacing_teacher TEXT, admin_comment TEXT, created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE replacement_requests_archive (id INTEGER PRIMARY KEY, teacher_name TEXT NOT NULL, request_date DATE NOT NULL, week_num INTEGER NOT NULL, num_den TEXT, classes INTEGER NOT NULL, subject TEXT NOT NULL, team TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'confirmed', replacing_teacher TEXT, admin_comment TEXT, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, archived_at TIMESTAMP DEFAULT NOW());
CREATE TABLE api.users (email TEXT PRIMARY KEY, password_hash TEXT NOT NULL, role TEXT NOT NULL, teacher_name TEXT, created_at TIMESTAMP DEFAULT NOW());

